problems = [{'id': 'DRAGON-01', 'title': 'Số Gấp Đôi', 'chapter': 'Phần I. Nhập - Xuất cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Trong hành trình luyện rồng, chú rồng con cần nhân đôi sức mạnh năng lượng của mình trước mỗi chuyến bay.\n\nCho một số nguyên $A$. Hãy viết chương trình in ra số lớn gấp đôi số $A$ (tức giá trị $2 \\times A$).', 'input_format': 'Một dòng duy nhất chứa số nguyên $A$ ($-10^9 \\le A \\le 10^9$).', 'output_format': 'In ra một số nguyên duy nhất là kết quả bài toán.', 'constraints': '$-10^9 \\le A \\le 10^9$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '23', 'sample_output': '46', 'hints': 'Với ngôn ngữ C, chú ý sử dụng kiểu dữ liệu `long long` nếu giá trị nhân đôi có thể vượt quá giới hạn 32-bit `int`.', 'python_starter': "# Bí kíp luyện rồng - Số Gấp Đôi\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Số Gấp Đôi\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        a = int(line)\n        print(a * 2)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long a;\n    if (scanf("%lld", &a) == 1) {\n        printf("%lld\\n", a * 2);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Đọc số nguyên $A$ và in ra $2 \\times A$.\n- **Độ phức tạp:** Thời gian $O(1)$, Bộ nhớ $O(1)$.\n- **Lưu ý bẫy:** Vì $A$ lên tới $10^9$, khi nhân đôi sẽ thành $2 \\times 10^9$. Trong C, giới hạn của `int` có dấu là khoảng $2.14 \\times 10^9$, do đó dùng kiểu `long long` là an toàn nhất để tránh tràn số.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu)', 'input_data': '23\n', 'expected_output': '46\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Số nhỏ)', 'input_data': '5\n', 'expected_output': '10\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (Số 0)', 'input_data': '0\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (Số âm)', 'input_data': '-99\n', 'expected_output': '-198\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test (Biên 10^9)', 'input_data': '1000000000\n', 'expected_output': '2000000000\n'}]}, {'id': 'DRAGON-02', 'title': 'Phép Tính #1', 'chapter': 'Phần I. Nhập - Xuất cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào ba số nguyên $A, B, C$. Hãy tính và in ra giá trị của biểu thức $(A - B) \\times C$.', 'input_format': 'Ba số nguyên $A, B, C$ viết trên cùng một dòng, cách nhau bởi một dấu cách.', 'output_format': 'In ra một số nguyên duy nhất là kết quả.', 'constraints': '$-10^4 \\le A, B, C \\le 10^4$', 'sample_input': '10 1 3', 'sample_output': '27', 'hints': 'Thực hiện phép trừ trong ngoặc $(A - B)$ trước rồi nhân với $C$.', 'python_starter': "# Bí kíp luyện rồng - Phép Tính #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phép Tính #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 3:\n        a, b, c = int(parts[0]), int(parts[1]), int(parts[2])\n        print((a - b) * c)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long a, b, c;\n    if (scanf("%lld %lld %lld", &a, &b, &c) == 3) {\n        printf("%lld\\n", (a - b) * c);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Thực hiện tuần tự: lấy hiệu $(A - B)$ rồi nhân với $C$.\n- Độ phức tạp $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1', 'input_data': '10 1 3\n', 'expected_output': '27\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (A == B)', 'input_data': '5 5 100\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (A < B)', 'input_data': '3 10 4\n', 'expected_output': '-28\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (Có số âm)', 'input_data': '0 5 -7\n', 'expected_output': '35\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số lớn', 'input_data': '10000 2000 5000\n', 'expected_output': '40000000\n'}]}, {'id': 'DRAGON-03', 'title': 'Ký Tự Hoa Sang Thường', 'chapter': 'Phần I. Nhập - Xuất & Ký tự', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': "Cho một chữ cái in hoa tiếng Anh (từ `'A'` đến `'Z'`). Hãy viết chương trình chuyển đổi và in ra chữ cái in thường tương ứng (từ `'a'` đến `'z'`).", 'input_format': 'Một dòng duy nhất chứa 1 ký tự là chữ cái in hoa.', 'output_format': 'In ra 1 ký tự duy nhất là chữ cái thường tương ứng.', 'constraints': "Ký tự thuộc ['A' .. 'Z'].", 'sample_input': 'A', 'sample_output': 'a', 'hints': 'Trong bảng ASCII, khoảng cách giữa chữ hoa và thường là 32: `c + 32`.', 'python_starter': "# Bí kíp luyện rồng - Ký Tự Hoa Sang Thường\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Ký Tự Hoa Sang Thường\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    ch = sys.stdin.read().strip()\n    if ch:\n        print(ch[0].lower())\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    char c;\n    if (scanf(" %c", &c) == 1) {\n        printf("%c\\n", c - \'A\' + \'a\');\n    }\n    return 0;\n}', 'editorial': "### Phân Tích & Hướng Dẫn Giải\n- Trong bảng mã ASCII, `'A'` có mã 65 và `'a'` có mã 97. Do đó `'c' - 'A' + 'a'` sẽ cho ra ký tự thường tương ứng.", 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1', 'input_data': 'A\n', 'expected_output': 'a\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2', 'input_data': 'Z\n', 'expected_output': 'z\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (M)', 'input_data': 'M\n', 'expected_output': 'm\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (B)', 'input_data': 'B\n', 'expected_output': 'b\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Test ngẫu nhiên (H)', 'input_data': 'H\n', 'expected_output': 'h\n'}]}, {'id': 'DRAGON-04', 'title': 'Phép Tính Phức Tạp', 'chapter': 'Phần I. Nhập - Xuất cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào hai số nguyên $A$ và $B$. Hãy in ra giá trị của biểu thức: $A + B + A \\times B$.', 'input_format': 'Hai số nguyên $A$ và $B$ cách nhau một khoảng trắng ($-1000 \\le A, B \\le 1000$).', 'output_format': 'In ra một số nguyên duy nhất là giá trị biểu thức.', 'constraints': '$-1000 \\le A, B \\le 1000$.', 'sample_input': '10 20', 'sample_output': '230', 'hints': 'Tính $A + B + A \\times B$.', 'python_starter': "# Bí kíp luyện rồng - Phép Tính Phức Tạp\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phép Tính Phức Tạp\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        a, b = int(parts[0]), int(parts[1])\n        print(a + b + a * b)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long a, b;\n    if (scanf("%lld %lld", &a, &b) == 2) {\n        printf("%lld\\n", a + b + a * b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Thực hiện phép toán theo thứ tự nhân trước cộng sau: $A + B + (A \\times B)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1', 'input_data': '10 20\n', 'expected_output': '230\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2', 'input_data': '1 1\n', 'expected_output': '3\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (0 0)', 'input_data': '0 0\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test có số âm', 'input_data': '-5 4\n', 'expected_output': '-21\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test 1000 1000', 'input_data': '1000 1000\n', 'expected_output': '1002000\n'}]}, {'id': 'DRAGON-05', 'title': 'Chuỗi Mở Đầu Ngày Mới', 'chapter': 'Phần V. Xử lý Chuỗi ký tự', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Cho chuỗi ký tự $Z$ gồm các ký tự chữ cái viết liền, không khoảng trắng. Hãy in ra chuỗi $Z$ theo thứ tự đảo ngược lại.', 'input_format': 'Một chuỗi ký tự $Z$ ($1 \\le |Z| \\le 1000$).', 'output_format': 'Chuỗi ký tự sau khi đảo ngược.', 'constraints': '$|Z| \\le 1000$', 'sample_input': 'oahcnix', 'sample_output': 'xinchao', 'hints': 'Trong C dùng vòng lặp từ `len-1` về `0`. Trong Python dùng slice `z[::-1]`.', 'python_starter': "# Bí kíp luyện rồng - Chuỗi Mở Đầu Ngày Mới\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Chuỗi Mở Đầu Ngày Mới\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    z = sys.stdin.read().strip()\n    print(z[::-1])\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[2005];\n    if (scanf("%2000s", s) == 1) {\n        int len = strlen(s);\n        for (int i = len - 1; i >= 0; i--) {\n            putchar(s[i]);\n        }\n        putchar(\'\\n\');\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Duyệt các ký tự của chuỗi từ vị trí cuối cùng về vị trí đầu tiên.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1', 'input_data': 'oahcnix\n', 'expected_output': 'xinchao\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2', 'input_data': 'codefun\n', 'expected_output': 'nufedoc\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (1 ký tự)', 'input_data': 'k\n', 'expected_output': 'k\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test đối xứng (Palindrome)', 'input_data': 'racecar\n', 'expected_output': 'racecar\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test chuỗi dài', 'input_data': 'DragonTrainingSecretScrollByCodefunVietnam2026\n', 'expected_output': '6202manteiVnufedoCyBllorcSterceSgniniarTnogarD\n'}]}, {'id': 'DRAGON-06', 'title': 'Vòng Tròn Chữ Cái', 'chapter': 'Phần I. Ký tự & Phép Modulo', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': "Nhập vào chữ cái in thường $C$ và số nguyên $N$ ($0 \\le N \\le 10^9$). Hãy in ra chữ cái in thường đứng sau $C$ đúng $N$ đơn vị theo vòng tròn bảng chữ cái tiếng Anh từ `'a'` đến `'z'`.", 'input_format': 'Một dòng chứa chữ cái thường $C$ và số nguyên $N$ cách nhau một khoảng trắng.', 'output_format': 'In ra một ký tự chữ cái thường duy nhất là đáp án.', 'constraints': "$0 \\le N \\le 10^9$; $C \\in ['a' .. 'z']$.", 'sample_input': 'z 1', 'sample_output': 'a', 'hints': "Dùng phép chia lấy dư: `(c - 'a' + n) % 26 + 'a'`.", 'python_starter': "# Bí kíp luyện rồng - Vòng Tròn Chữ Cái\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Vòng Tròn Chữ Cái\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        c = parts[0]\n        n = int(parts[1])\n        base = ord('a')\n        res = chr(base + (ord(c) - base + n) % 26)\n        print(res)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    char c;\n    long long n;\n    if (scanf(" %c %lld", &c, &n) == 2) {\n        char res = \'a\' + (c - \'a\' + n) % 26;\n        printf("%c\\n", res);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Bảng chữ cái có 26 ký tự khép kín, vị trí mới là `(vị trí hiện tại + N) % 26`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (z 1 -> a)', 'input_data': 'z 1\n', 'expected_output': 'a\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (a 2 -> c)', 'input_data': 'a 2\n', 'expected_output': 'c\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (N = 0)', 'input_data': 'y 0\n', 'expected_output': 'y\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (N = 26)', 'input_data': 'd 26\n', 'expected_output': 'd\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test N = 10^9 + 1', 'input_data': 'a 1000000001\n', 'expected_output': 'n\n'}]}, {'id': 'DRAGON-07', 'title': 'Kiểm Tra Số Nguyên Tố', 'chapter': 'Phần II. Vòng lặp & Điều kiện', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Cho một số nguyên $N$. Hãy kiểm tra xem $N$ có phải là số nguyên tố hay không. In ra `YES` nếu đúng, ngược lại in ra `NO`.', 'input_format': 'Một dòng duy nhất chứa số nguyên $N$ ($-10^9 \\le N \\le 10^9$).', 'output_format': 'In ra `YES` hoặc `NO`.', 'constraints': '$-10^9 \\le N \\le 10^9$', 'sample_input': '7', 'sample_output': 'YES', 'hints': 'Kiểm tra ước từ 2 đến căn bậc 2 của N.', 'python_starter': "# Bí kíp luyện rồng - Kiểm Tra Số Nguyên Tố\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Kiểm Tra Số Nguyên Tố\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef is_prime(n):\n    if n < 2:\n        return False\n    if n in (2, 3):\n        return True\n    if n % 2 == 0 or n % 3 == 0:\n        return False\n    i = 5\n    while i * i <= n:\n        if n % i == 0 or n % (i + 2) == 0:\n            return False\n        i += 6\n    return True\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        print("YES" if is_prime(int(line)) else "NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <stdbool.h>\n\nbool is_prime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) return false;\n    }\n    return true;\n}\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        if (is_prime(n)) printf("YES\\n");\n        else printf("NO\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Số nguyên tố là số $> 1$ chỉ có 2 ước 1 và chính nó.\n- Để đạt độ phức tạp $O(\\sqrt{N})$, ta kiểm tra các số chia $i$ từ $2$ đến $\\lfloor\\sqrt{N}\\rfloor$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1', 'input_data': '7\n', 'expected_output': 'YES\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2', 'input_data': '10\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (1)', 'input_data': '1\n', 'expected_output': 'NO\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (2)', 'input_data': '2\n', 'expected_output': 'YES\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test nguyên tố lớn', 'input_data': '999983\n', 'expected_output': 'YES\n'}]}, {'id': 'DRAGON-08', 'title': 'Số Fibonacci Thứ N', 'chapter': 'Phần III. Dãy số & Vòng lặp', 'difficulty': 'Khó', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Dãy số Fibonacci kinh điển được định nghĩa: $F_1 = 1, F_2 = 1, F_n = F_{n-1} + F_{n-2}$ ($n \\ge 3$). Cho số nguyên $N$ ($1 \\le N \\le 45$). Hãy tìm và in ra số Fibonacci thứ $N$.', 'input_format': 'Một dòng duy nhất chứa số nguyên $N$ ($1 \\le N \\le 45$).', 'output_format': 'In ra giá trị $F_N$.', 'constraints': '$1 \\le N \\le 45$.', 'sample_input': '6', 'sample_output': '8', 'hints': 'Dùng vòng lặp $O(N)$ thay vì đệ quy ngây thơ $O(2^N)$ để tránh bị TLE.', 'python_starter': "# Bí kíp luyện rồng - Số Fibonacci Thứ N\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Số Fibonacci Thứ N\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line: return\n    n = int(line)\n    if n <= 2:\n        print(1)\n        return\n    a, b = 1, 1\n    for _ in range(3, n + 1):\n        a, b = b, a + b\n    print(b)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n <= 2) { printf("1\\n"); return 0; }\n        long long a = 1, b = 1, c = 0;\n        for (int i = 3; i <= n; i++) {\n            c = a + b;\n            a = b;\n            b = c;\n        }\n        printf("%lld\\n", b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Sử dụng quy hoạch động hoặc 2 biến lưu trạng thái để tính trong $O(N)$ thời gian và $O(1)$ bộ nhớ.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (F(6) = 8)', 'input_data': '6\n', 'expected_output': '8\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (F(1) = 1)', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (F(2) = 1)', 'input_data': '2\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test trung bình (F(10) = 55)', 'input_data': '10\n', 'expected_output': '55\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test N = 45', 'input_data': '45\n', 'expected_output': '1134903170\n'}]}]
